#include <stdio.h>
#include <stdlib.h>

typedef struct Node{int value;struct Node *next;} Node;
void clear(Node *p){while(p){Node *next=p->next;free(p);p=next;}}
int main(void) {
    int n,x;Node *head=NULL;
    if(scanf("%d",&n)!=1 || n<0 || n>100)return 1;
    for(int i=0;i<n;i++){if(scanf("%d",&x)!=1){clear(head);return 1;}Node *p=malloc(sizeof *p);if(!p){clear(head);return 1;}p->value=x;p->next=head;head=p;}
    for(Node *p=head;p;p=p->next)printf("%d\n",p->value);
    clear(head);
    return 0;
}
